 D=R/'data/venue_refs/floor_plans_v3'/scene;W=R/'out/infinigen_v2'/f'kr_{scene}_{seed}';blends=[p for p in W.glob('furnished_r*.blend')];blend=max(blends,key=lambda p:p.stat().st_mtime) if blends else W/'full/scene.blend';furnished=bool(blends);reviews=sorted([p for p in W.glob('review_r*') if p.is_dir()],key=lambda p:p.stat().st_mtime);display=next((p for p in reversed(reviews) if completed_frames(p)),W/'review_r1');job=json.loads((display/'job.json').read_text()) if (display/'job.json').exists() else {};display_reviews=[p for p in reviews if (p/'job.json').exists() and json.loads((p/'job.json').read_text()).get('source')==job.get('source')];frames=sorted([f for p in display_reviews for f in completed_frames(p)]);queue=json.loads((W/'render_queue_r1.json').read_text()) if (W/'render_queue_r1.json').exists() else {};total_frames=sum(len(completed_frames(p)) for p in reviews)
