 if frames and job.get('exit_code')==0:status='rendered_visual_review_pending'
 candidate_jobs=[json.loads((p/'job.json').read_text()) for p in reviews if (p/'job.json').exists() and json.loads((p/'job.json').read_text()).get('source')==str(blend.resolve())];candidate_job=candidate_jobs[-1] if candidate_jobs else {}
 if candidate_job.get('phase')=='live' and job.get('source')==str(blend.resolve()):status='rendered_partial_review_pending' if frames else 'furnished_render_live'
 if job.get('source')!=str(blend.resolve()):status='revised_candidate_render_live_old_evidence' if candidate_job.get('phase')=='live' else 'revised_candidate_pending_old_evidence'
