 engfiles=sorted(D.glob('engineering_review_r*.json'),key=lambda p:p.stat().st_mtime);engineering=json.loads(engfiles[-1].read_text())['findings'] if engfiles else [];engineering_html='<h3>Actual geometry checks</h3><ul>'+''.join('<li>'+html.escape(x)+'</li>' for x in engineering)+'</ul>' if engineering else ''
